import{_ as m,c as e,b as a,d as o,e as p,a as t,w as i,r,o as c,f as l}from"./app-BC3GIMfQ.js";const h="/assets/image1-D2Tx29cd.png",g="/assets/image2-BLiWi1qc.png",d="/assets/image3-DxOz7g7G.png",N="/assets/image4-Tn_Qcq7o.png",u="/assets/image5-DemaaRL0.png",S="/assets/image6-CZ0P6UP2.png",P="/assets/image7-DfMdTGtw.png",x="/assets/algo1-D-k2Z8oX.png",v="/assets/image8-C5OY1vCz.png",w="/assets/table1-B-Lg3Es3.png",y="/assets/image9-D3kBkCSl.png",A="/assets/image10-BThVDscz.png",M="/assets/image11-BOCAxaKK.png",U="/assets/image12-DTF8qHb9.png",b="/assets/table2-CRNx88hL.png",k="/assets/table3-zk5VFxso.png",I={},D={class:"table-of-contents"};function G(f,s){const n=r("router-link");return c(),e("div",null,[s[19]||(s[19]=a("h1",{id:"fusionanns-一种用于十亿级近似最近邻搜索的高效-cpu-gpu-协同处理架构",tabindex:"-1"},[a("a",{class:"header-anchor",href:"#fusionanns-一种用于十亿级近似最近邻搜索的高效-cpu-gpu-协同处理架构"},[a("span",null,"FusionANNS：一种用于十亿级近似最近邻搜索的高效 CPU/GPU 协同处理架构")])],-1)),s[20]||(s[20]=a("p",null,[a("strong",null,"FusionANNS: An Efficient CPU/GPU Cooperative Processing Architecture for Billion-scale Approximate Nearest Neighbor Search")],-1)),o(" more "),s[21]||(s[21]=p('<div class="hint-container info"><p class="hint-container-title">相关信息</p><p><strong>论文</strong>: <a href="https://arxiv.org/abs/2409.16576" target="_blank" rel="noopener noreferrer">FusionANNS: An Efficient CPU/GPU Cooperative Processing Architecture for Billion-scale Approximate Nearest Neighbor Search</a><br><strong>代码</strong>: 未提供<br><strong>解读</strong>:<br> 本文提出了一种名为 FusionANNS 的新系统，旨在解决十亿级别向量数据集上的近似最近邻搜索（ANNS）问题。其核心思想是构建一个高性价比的软硬件协同系统，仅使用一块入门级 GPU 和 SSD，就能同时实现高吞吐、低延迟、高精度和低成本。</p><p>FusionANNS 的关键创新在于其 <strong>CPU/GPU 协同过滤和重排机制</strong>，通过三项新颖设计来打破传统方案中的 I/O 性能瓶颈：</p><ol><li><strong>多层级索引（Multi-tiered Indexing）</strong>：这是系统的架构核心。它将索引的不同部分智能地分布在不同的存储层级上： <ul><li><strong>CPU 主存</strong>：存储导航图（navigation graph）和每个 posting list 的向量 ID 元数据。这部分数据量小，访问频繁。</li><li><strong>GPU HBM</strong>：存储所有向量的 PQ（Product Quantization）压缩版本。利用 HBM 的高带宽进行快速的近似距离计算（过滤阶段）。</li><li><strong>SSD</strong>：存储原始的全精度向量，仅在最后的重排阶段按需读取。<br> 这种设计极大减少了 CPU 和 GPU 之间的数据传输量，因为在过滤阶段只需传输轻量的向量 ID，而非完整的向量数据。</li></ul></li><li><strong>启发式重排（Heuristic Re-ranking）</strong>：为了在保证高精度的同时避免不必要的计算和 I/O，系统将重排过程拆分为多个小批次（mini-batches）。在每个批次后，通过一个轻量级反馈模型判断后续批次对提升精度的贡献。如果贡献过小，则提前终止重排，从而为不同查询动态地确定最小重排向量数。</li><li><strong>冗余感知 I/O 去重（Redundant-aware I/O Deduplication）</strong>：通过优化 SSD 上的数据布局，将相似向量紧凑存储，提升空间局部性。这使得系统可以在批次内合并对同一 SSD 页面的读取请求，并在批次间利用 DRAM 缓存消除重复读取，显著降低了读放大效应。</li></ol><p>实验结果表明，与业界领先的基于 SSD 的 SPANN 系统和基于 GPU 的内存系统 RUMMY 相比，FusionANNS 在吞吐率（QPS）和成本效益上均取得了数倍的提升，同时保持了低延迟和高精度。这使其成为大规模 AI 应用（如 RAG）中一个极具吸引力的向量检索解决方案。</p></div>',1)),a("nav",D,[a("ul",null,[a("li",null,[t(n,{to:"#摘要"},{default:i(()=>s[0]||(s[0]=[l("摘要")])),_:1,__:[0]})]),a("li",null,[t(n,{to:"#i、引言"},{default:i(()=>s[1]||(s[1]=[l("I、引言")])),_:1,__:[1]})]),a("li",null,[t(n,{to:"#ii、背景与动机"},{default:i(()=>s[2]||(s[2]=[l("II、背景与动机")])),_:1,__:[2]}),a("ul",null,[a("li",null,[t(n,{to:"#a-anns-的索引技术"},{default:i(()=>s[3]||(s[3]=[l("A. ANNS 的索引技术")])),_:1,__:[3]})]),a("li",null,[t(n,{to:"#b-乘积量化"},{default:i(()=>s[4]||(s[4]=[l("B. 乘积量化")])),_:1,__:[4]})]),a("li",null,[t(n,{to:"#c-主要思想与挑战"},{default:i(()=>s[5]||(s[5]=[l("C. 主要思想与挑战")])),_:1,__:[5]})])])]),a("li",null,[t(n,{to:"#iii、fusionanns-概述"},{default:i(()=>s[6]||(s[6]=[l("III、FusionANNS 概述")])),_:1,__:[6]})]),a("li",null,[t(n,{to:"#iv、fusionanns-设计"},{default:i(()=>s[7]||(s[7]=[l("IV、FusionANNS 设计")])),_:1,__:[7]}),a("ul",null,[a("li",null,[t(n,{to:"#a-多层级索引"},{default:i(()=>s[8]||(s[8]=[l("A. 多层级索引")])),_:1,__:[8]})]),a("li",null,[t(n,{to:"#b-启发式重排"},{default:i(()=>s[9]||(s[9]=[l("B. 启发式重排")])),_:1,__:[9]})]),a("li",null,[t(n,{to:"#c-冗余感知的-i-o-去重"},{default:i(()=>s[10]||(s[10]=[l("C. 冗余感知的 I/O 去重")])),_:1,__:[10]})])])]),a("li",null,[t(n,{to:"#v、实现"},{default:i(()=>s[11]||(s[11]=[l("V、实现")])),_:1,__:[11]})]),a("li",null,[t(n,{to:"#vi、评估"},{default:i(()=>s[12]||(s[12]=[l("VI、评估")])),_:1,__:[12]}),a("ul",null,[a("li",null,[t(n,{to:"#a-性能"},{default:i(()=>s[13]||(s[13]=[l("A. 性能")])),_:1,__:[13]})]),a("li",null,[t(n,{to:"#b-可扩展性"},{default:i(()=>s[14]||(s[14]=[l("B. 可扩展性")])),_:1,__:[14]})]),a("li",null,[t(n,{to:"#c-单项技术的有效性"},{default:i(()=>s[15]||(s[15]=[l("C. 单项技术的有效性")])),_:1,__:[15]})]),a("li",null,[t(n,{to:"#d-成本和内存效率"},{default:i(()=>s[16]||(s[16]=[l("D. 成本和内存效率")])),_:1,__:[16]})])])]),a("li",null,[t(n,{to:"#vii、相关工作"},{default:i(()=>s[17]||(s[17]=[l("VII、相关工作")])),_:1,__:[17]})]),a("li",null,[t(n,{to:"#viii、结论"},{default:i(()=>s[18]||(s[18]=[l("VIII、结论")])),_:1,__:[18]})])])]),s[22]||(s[22]=p('<h2 id="摘要" tabindex="-1"><a class="header-anchor" href="#摘要"><span>摘要</span></a></h2><ul><li><p>近似最近邻搜索（ANNS）已成为数据库和 AI 基础设施的关键组成部分。日益增长的向量数据集在性能、成本和准确性方面给 ANNS 服务带来了巨大挑战。现有的现代 ANNS 系统无法同时解决这些问题。</p></li><li><p>我们提出了 FusionANNS，一个使用 SSD 和仅一块入门级 GPU，为十亿级数据集设计的具备高吞吐、低延迟、高成本效益和高准确性的 ANNS 系统。FusionANNS 的核心思想在于其 CPU/GPU 协同过滤和重排机制，该机制能显著减少跨 CPU、GPU 和 SSD 的 I/O 操作，从而突破 I/O 性能瓶颈。具体来说，我们提出了三项创新设计：（1）多层级索引，以避免 CPU 和 GPU 之间的数据交换；（2）启发式重排，以在保证高准确性的同时消除不必要的 I/O 和计算；以及（3）冗余感知的 I/O 去重，以进一步提高 I/O 效率。我们实现了 FusionANNS，并将其与最先进的基于 SSD 的 ANNS 系统 SPANN 以及 GPU 加速的内存 ANNS 系统 RUMMY 进行了比较。实验结果表明，FusionANNS 实现了：1) 与 SPANN 相比，QPS（每秒查询数）提高了 9.4-13.1 倍，成本效益提高了 5.7-8.8 倍；2) 与 RUMMY 相比，QPS 提高了 2-4.9 倍，成本效益提高了 2.3-6.8 倍，同时保证了低延迟和高准确性。</p></li></ul><h2 id="i、引言" tabindex="-1"><a class="header-anchor" href="#i、引言"><span>I、引言</span></a></h2><ul><li><p>近似最近邻搜索（ANNS）在高维空间中指为给定查询向量找到最相似的 top-k 个向量。它在许多领域有广泛应用，包括数据挖掘 [1]、搜索引擎 [2] 以及 AI 驱动的推荐系统 [3, 4]。特别地，得益于近期大型语言模型（LLM）[5-8] 的蓬勃发展，ANNS 系统已成为现代 AI 基础设施的关键组成部分。图1展示了一个典型的检索增强生成（RAG）框架。</p></li><li><p><img src="'+h+'" alt="image1" loading="lazy"></p></li><li><p>领域特定知识首先被嵌入为高维向量并存储在向量数据库中。当聊天机器人接收到查询时，它使用 ANNS 引擎从向量数据库中检索最相关的知识，从而允许 LLM 利用这些知识作为额外上下文，以进行更准确的推理。</p></li><li><p>ANNS 是一个典型的内存密集型和计算密集型应用。大多数 ANNS 系统 [9-13] 利用倒排文件（IVF）[14-16] 或基于图 [12, 13, 17] 的索引来加速 ANNS。对于十亿级数据集，这些索引通常需要大量的内存资源。例如，最先进的基于 IVF 的 RUMMY [9] 和基于图的 Bang [10] 需要 TB 级的内存空间来容纳十亿级向量及其索引。巨大的内存需求显著增加了总拥有成本（TCO），阻碍了 ANNS 扩展到极大规模的数据集（例如，数千亿向量）。尽管内存需求巨大，ANNS 在计算上也同样密集，因为它需要在高维空间中进行大量的向量间距离计算，特别是对于大规模数据集。随着向量数据库的快速增长，ANNS 已成为 RAG 场景中的新性能瓶颈 [9]，可能占到 LLM 查询总延迟的约 50% [18]。</p></li><li><p>为了降低 ANNS 所需的内存成本，主要有两种方法，即分层索引（Hierarchical Indexing, HI）[15, 19] 和乘积量化（Product Quantization, PQ）[20, 21]。首先，分层索引方法通过将索引 [15, 22] 存储在 SSD 上来减少内存消耗。通常，微软的商业 ANNS 系统 SPANN [14, 15] 将所有基于 IVF 的索引（即 posting lists）存储在 SSD 上，并使用导航图在内存中维护这些 posting lists 的质心。尽管 SPANN 实现了低延迟，但我们发现其在并发查询下的吞吐量相当有限，在高端 SSD 上仅用四个 CPU 线程就达到峰值（第2.1节）。这种有限的可扩展性妨碍了其在需要高吞吐量的 AI 应用中的实用性。其次，PQ 是另一种节省内存成本的有效方法。这种向量压缩技术可以显著减少高维向量的内存占用高达 95%，并且还能将 ANNS 的速度提升数倍 [20]。然而，由于 PQ 是一种有损压缩方案，更高的压缩率通常意味着更低的查询准确率。对于一些要求高准确率（例如，recall &gt; 90%）的场景，这通常是不可接受的 [23]。</p></li><li><p>为了应对计算挑战，GPU 已被越来越多地用于加速 ANNS 中涉及的大量距离计算。近期的基于 GPU 的 ANNS 解决方案 [9, 10, 20, 24-26] 在处理能装入 GPU 高带宽内存（HBM）的小型数据集时展现了高效率。然而，对于十亿级数据集，基于 GPU 的方法可能会遭受显著的性能下降。我们的实验表明，当 SPANN 直接采用 GPU 进行距离计算时，ANNS 的性能甚至下降了 10%（第2.3节）。根本原因在于 HBM 容量有限，导致在 GPU 的 HBM、主机内存和 SSD 之间发生大量的数据移动。</p></li><li><p>尽管上述方法在某种程度上可以解决性能/成本/准确性问题，但没有一种方法能够同时为十亿级 ANNS 服务提供高吞吐、低延迟、高成本效益和高准确性。直观上，人们可以将分层索引、乘积量化和 GPU 加速技术结合起来，以实现最优的 ANNS 解决方案。然而，我们发现这些技术的组合甚至会导致比单独使用分层索引的 SPANN 更差的性能（第2.3节）。总的来说，在 GPU 加速的 ANNS 系统中，将分层索引与乘积量化进行协同仍然面临几个挑战。</p></li><li><p><strong>挑战 1</strong>：为了提高查询准确性和效率，大多数 ANNS 系统 [14, 15] 利用一种复制策略来构建高质量的 IVF 索引，其中边界向量被复制到相邻的 posting lists 中。这会显著扩大索引的大小，使其比原始向量大 8 倍 [14, 15]。即使使用 PQ 对这些索引进行压缩，GPU 的 HBM 仍然无法容纳所有压缩后的索引，导致 GPU 和 CPU 之间发生大量数据交换。<strong>挑战 2</strong>：由于 PQ 会带来不可忽略的准确性损失，它通常与向量重排过程相关联以提高查询准确性。然而，由于不同压缩向量的准确性损失差异很大，因此在给定的准确性约束下，为每个查询确定需要重排的最小向量数量是具有挑战性的。<strong>挑战 3</strong>：由于一个原始向量（128-384 字节）远小于现代 NVMe SSD 的最小读取粒度（4 KB），每个对原始向量的请求通常会引起显著的读放大，导致重排过程中的 I/O 效率低下。</p></li><li><p>在本文中，我们提出了 FusionANNS，一个用于十亿级 ANNS 的“CPU + GPU”协同处理架构。FusionANNS 仅使用一块入门级 GPU，就能同时实现高吞吐、低延迟、高成本效益和高准确性。FusionANNS 的核心思想是通过 CPU/GPU 协同过滤和重排来最小化跨 GPU、CPU 和 SSD 的数据交换。具体来说，我们提出了三个新颖的设计来应对上述挑战。</p></li><li><p>首先，我们提出了一种新颖的多层级索引结构，以实现 CPU/GPU 协同过滤。FusionANNS 将 (i) 原始向量存储在 SSD 上，并将 (ii) 使用 PQ 压缩的向量存储在 GPU 的 HBM 中，同时在主机内存中仅维护 (iii) 每个 posting list 的向量 ID 和一个导航图。由于 HBM 只存储高度压缩的 PQ 向量而不是压缩的 posting lists，它可以容纳十亿级数据集中的所有压缩向量。当收到一个查询时，主机 CPU 首先遍历内存中的导航图以找到 top-m 个最近的 posting lists，然后仅将它们的向量 ID（不包括向量内容）传输到 GPU 进行距离计算。通过这种方式，FusionANNS 可以显著减少 CPU 和 GPU 之间的数据传输。</p></li><li><p>其次，我们提出了启发式重排来提高查询准确性，同时避免不必要的 I/O 操作和距离计算。我们将重排过程分成多个小批次（mini-batches）并顺序执行它们。一旦一个小批次完成，我们利用一个轻量级的反馈控制模型来检查后续的小批次是否有助于提高查询准确性，并在后续小批次对查询准确性的贡献很小时立即终止重排过程。</p></li><li><p>第三，我们提出了冗余感知的 I/O 去重，以进一步提高重排过程中的 I/O 效率。我们将具有高相似度的向量紧凑地存储，以提高 SSD 上的空间局部性。这种优化的存储布局支持两种 I/O 去重机制：1) 在一个小批次内合并映射到同一 SSD 页面的多个 I/O，以减轻读放大；2) 充分利用 DRAM 缓冲区以消除后续小批次中的冗余 I/O。</p></li><li><p>总的来说，我们做出了以下贡献：</p><ul><li>我们设计了 FusionANNS，这是第一个 GPU 加速的基于 SSD 的 ANNS 系统，它能同时为十亿级数据集实现高吞吐、低延迟、高成本效益和高准确性。</li><li>针对<strong>挑战 1</strong>，我们提出了一种新颖的多层级索引，它能实现 GPU/CPU 协同过滤，从而显著减少 CPU 和 GPU 之间的数据传输。</li><li>针对<strong>挑战 2</strong>，我们提出了启发式重排，以在重排过程中消除不必要的 I/O 和计算。</li><li>针对<strong>挑战 3</strong>，我们提出了基于优化存储布局的冗余感知 I/O 去重，以进一步提升 I/O 效率。</li><li>我们在一台配备入门级 GPU 的通用服务器上评估了 FusionANNS。实验结果表明，与最先进的基于 SSD 的系统 SPANN 和 GPU 加速的内存系统 RUMMY 相比，FusionANNS 的 QPS 分别提高了 13.1 倍和 4.9 倍，成本效益分别提高了 8.8 倍和 6.8 倍，同时保证了低延迟和高准确性。</li></ul></li></ul><h2 id="ii、背景与动机" tabindex="-1"><a class="header-anchor" href="#ii、背景与动机"><span>II、背景与动机</span></a></h2><ul><li>在本节中，我们首先介绍两种 ANNS 索引技术和向量的乘积量化（PQ），然后提出我们的主要思想并分析其关键挑战，这些挑战激发了 FusionANNS 的设计。</li></ul><h3 id="a-anns-的索引技术" tabindex="-1"><a class="header-anchor" href="#a-anns-的索引技术"><span>A. ANNS 的索引技术</span></a></h3><ul><li><p>大多数 ANNS 算法利用欧氏距离等距离度量来为给定查询向量找到 top-k 个最近邻。对于高维和大规模数据集，由于维度诅咒 [27]，计算成本非常高。为了解决这个问题，大多数 ANNS 算法 [16, 17, 28-32] 利用索引技术来剪枝那些不太可能包含最近邻的数据区域。这些索引可以通过缩小搜索空间来显著提高查询性能，但也会显著增加内存消耗，特别是对于大型数据集。在各种索引技术中，IVF [15, 16, 31, 32] 和基于图的索引 [17, 33] 因其高效率而被广泛使用。</p></li><li><p><strong>基于图的索引</strong>通常将向量组织成一个邻近图结构，其中顶点和边分别代表向量和两个顶点之间的距离。收到查询后，ANNS 引擎从一个给定的顶点开始遍历图来找到 top-k 个最近邻。DiskANN [22] 是一个典型的基于图的 ANNS 解决方案。它使用 SSD 存储十亿级数据集的图索引，同时在主内存中保留一些频繁访问的顶点。尽管 DiskANN 是一个内存高效的 ANNS 解决方案，但由于大规模数据集的迭代路径较长，其查询延迟较高。</p></li><li><p><strong>IVF 索引</strong>是一种流行的大规模数据集索引技术，这些数据集存储在 SSD 上。为了创建 IVF 索引，数据集通常使用聚类算法 [34] 划分为许多 posting lists，每个 posting list 由其质心表示。最近的研究 [9, 35] 表明，对于十亿级数据集，IVF 索引 [15] 比最先进的基于图的索引 [22] 更高效。SPANN [15] 是一个使用 IVF 索引的最先进的十亿级 ANNS 系统。与传统的 IVF 索引不同，SPANN 通过将簇的边界向量复制到相邻的 posting lists 中来构建一个高级 IVF 索引。这种复制机制显著扩大了向量索引的大小达 8 倍，但提高了查询的准确性和效率。如图2所示，SPANN 将所有 posting lists 存储在 SSD 上，同时使用一个图索引在内存中维护这些 posting lists 的质心。收到查询后，SPANN 遍历内存中的图以识别 top-m 个最近的 posting lists，并将它们加载到主机主内存中。然后，它通过距离计算在这些 m 个 posting lists 中找到 top-k（<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>k</mi><mo>&lt;</mo><mi>m</mi></mrow><annotation encoding="application/x-tex">k &lt; m</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7335em;vertical-align:-0.0391em;"></span><span class="mord mathnormal" style="margin-right:0.03148em;">k</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">&lt;</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">m</span></span></span></span>）个最近邻。</p></li><li><p><img src="'+g+'" alt="image2" loading="lazy"></p></li><li><p>尽管 SPANN 实现了与内存 ANNS 方法相媲美的低延迟，但我们发现它对于并发查询的吞吐量相当有限。如图3a所示，SPANN 仅用四个 CPU 线程就达到了峰值 QPS，其吞吐量无法随更多线程扩展。我们统计了查询在两个阶段的延迟：（i）内存中的图遍历，和（ii）处理来自 SSD 的 posting lists。图3b显示，查询延迟几乎随线程数线性增加。然而，图遍历的延迟几乎保持稳定，而处理 posting lists 的延迟则随线程数显著增加。原因在于多个查询并发地从 SSD 读取许多大尺寸的 posting lists，导致了严重的 I/O 争用和高延迟。</p></li><li><p><img src="'+d+'" alt="image3" loading="lazy"></p></li></ul><h3 id="b-乘积量化" tabindex="-1"><a class="header-anchor" href="#b-乘积量化"><span>B. 乘积量化</span></a></h3><ul><li><p>为了减少大规模数据集的向量索引大小和计算成本，乘积量化（PQ）[32] 近期被用于压缩高维向量。假设一个包含 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>N</mi></mrow><annotation encoding="application/x-tex">N</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.10903em;">N</span></span></span></span> 个向量的数据集使用 PQ 进行压缩，这些向量首先被均匀地划分为 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>M</mi></mrow><annotation encoding="application/x-tex">M</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.10903em;">M</span></span></span></span> 个子空间，每个子空间包含 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>N</mi></mrow><annotation encoding="application/x-tex">N</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.10903em;">N</span></span></span></span> 个子向量。然后，对这些子向量进行聚类以生成一个码本（codebook），该码本包含所有簇的一组质心。该码本允许每个子向量由其最近的质心来近似。每个子空间的簇数量通常设置为 256，允许每个簇 ID 由一个字节表示。一旦所有码本生成完毕，每个向量可以被压缩成一个 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>M</mi></mrow><annotation encoding="application/x-tex">M</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.10903em;">M</span></span></span></span> 字节的 PQ 码。收到查询后，首先生成一个距离查找表，包含每个子查询向量与每个子空间质心之间的所有距离。然后，查询向量 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>q</mi></mrow><annotation encoding="application/x-tex">q</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.03588em;">q</span></span></span></span> 与压缩向量 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>v</mi></mrow><annotation encoding="application/x-tex">v</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.03588em;">v</span></span></span></span> 之间的近似距离可以表示为：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mtable width="100%"><mtr><mtd width="50%"></mtd><mtd><mrow><mi>d</mi><mi>i</mi><mi>s</mi><mi>t</mi><mo stretchy="false">(</mo><mi>q</mi><mo separator="true">,</mo><mi>v</mi><mo stretchy="false">)</mo><mo>=</mo><munderover><mo>∑</mo><mrow><mi>i</mi><mo>=</mo><mn>1</mn></mrow><mi>M</mi></munderover><mi>d</mi><mi>i</mi><mi>s</mi><mi>t</mi><mo stretchy="false">(</mo><msub><mi>q</mi><mi>i</mi></msub><mo separator="true">,</mo><msub><mi>c</mi><mi>i</mi></msub><mo stretchy="false">(</mo><msub><mi>v</mi><mi>i</mi></msub><mo stretchy="false">)</mo><mo stretchy="false">)</mo></mrow></mtd><mtd width="50%"></mtd><mtd><mtext>(1)</mtext></mtd></mtr></mtable><annotation encoding="application/x-tex">dist (q,v) = \\sum_{i=1}^{M} dist (q_i, c_i(v_i)) \\tag{1} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">d</span><span class="mord mathnormal">i</span><span class="mord mathnormal">s</span><span class="mord mathnormal">t</span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.03588em;">q</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.03588em;">v</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:3.106em;vertical-align:-1.2777em;"></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.8283em;"><span style="top:-1.8723em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span><span class="mrel mtight">=</span><span class="mord mtight">1</span></span></span></span><span style="top:-3.05em;"><span class="pstrut" style="height:3.05em;"></span><span><span class="mop op-symbol large-op">∑</span></span></span><span style="top:-4.3em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.10903em;">M</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:1.2777em;"><span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">d</span><span class="mord mathnormal">i</span><span class="mord mathnormal">s</span><span class="mord mathnormal">t</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.03588em;">q</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">c</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.03588em;">v</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">))</span></span><span class="tag"><span class="strut" style="height:3.106em;vertical-align:-1.2777em;"></span><span class="mord text"><span class="mord">(</span><span class="mord"><span class="mord">1</span></span><span class="mord">)</span></span></span></span></span></span></p><p>其中 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>M</mi></mrow><annotation encoding="application/x-tex">M</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.10903em;">M</span></span></span></span> 表示子空间的总数，<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>q</mi><mi>i</mi></msub></mrow><annotation encoding="application/x-tex">q_i</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.03588em;">q</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 表示第 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>i</mi></mrow><annotation encoding="application/x-tex">i</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6595em;"></span><span class="mord mathnormal">i</span></span></span></span> 个子查询向量，<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>c</mi><mi>i</mi></msub><mo stretchy="false">(</mo><msub><mi>v</mi><mi>i</mi></msub><mo stretchy="false">)</mo></mrow><annotation encoding="application/x-tex">c_i(v_i)</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal">c</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.03588em;">v</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span> 表示压缩向量第 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>i</mi></mrow><annotation encoding="application/x-tex">i</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6595em;"></span><span class="mord mathnormal">i</span></span></span></span> 个子空间的质心。因此，通过使用 PQ 码作为地址查找距离表，可以轻松检索到 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>q</mi><mi>i</mi></msub></mrow><annotation encoding="application/x-tex">q_i</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.03588em;">q</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 和 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>c</mi><mi>i</mi></msub><mo stretchy="false">(</mo><msub><mi>v</mi><mi>i</mi></msub><mo stretchy="false">)</mo></mrow><annotation encoding="application/x-tex">c_i(v_i)</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal">c</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.03588em;">v</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span> 之间的距离。最后，将所有 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>d</mi><mi>i</mi><mi>s</mi><mi>t</mi><mo stretchy="false">(</mo><msub><mi>q</mi><mi>i</mi></msub><mo separator="true">,</mo><msub><mi>c</mi><mi>i</mi></msub><mo stretchy="false">(</mo><msub><mi>v</mi><mi>i</mi></msub><mo stretchy="false">)</mo><mo stretchy="false">)</mo></mrow><annotation encoding="application/x-tex">dist(q_i, c_i(v_i))</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">d</span><span class="mord mathnormal">i</span><span class="mord mathnormal">s</span><span class="mord mathnormal">t</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.03588em;">q</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">c</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.03588em;">v</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">))</span></span></span></span> 相加即可得到 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>q</mi></mrow><annotation encoding="application/x-tex">q</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.03588em;">q</span></span></span></span> 和 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>v</mi></mrow><annotation encoding="application/x-tex">v</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.03588em;">v</span></span></span></span> 之间的距离。</p></li><li><p>本质上，PQ 将向量间的距离计算转换为多次内存访问操作，因此对传统基于 CPU 的计算架构构成了重大挑战，因为 DRAM 访问延迟相对较高。因此，PQ 通常由 GPU 加速 [21, 32]，因为 GPU 可以充分利用其高带宽内存来提高查询性能。</p></li></ul><h3 id="c-主要思想与挑战" tabindex="-1"><a class="header-anchor" href="#c-主要思想与挑战"><span>C. 主要思想与挑战</span></a></h3><ul><li><p>为了规避十亿级数据集带来的巨大计算和内存资源挑战，我们的目标是设计一个使用 SSD 和入门级 GPU 的高吞吐、低延迟、高成本效益和高准确性的 ANNS 系统。然而，设计一个 GPU 加速的 ANNS 系统面临一个重大挑战，即 GPU 的 HBM 容量有限，这会导致 GPU 和 CPU 之间发生大量数据交换，从而显著降低大规模数据集的 ANNS 性能。</p></li><li><p><strong>一个使用 PQ 和 HI 的直接解决方案</strong>。幸运的是，PQ 技术可以显著减少向量的内存占用，从而缓解 CPU 和 GPU 之间数据传输相关的性能瓶颈。因此，PQ 有潜力充分利用 GPU 的能力来加速 ANNS 中涉及的距离计算 [20]。在这里，我们首先讨论一个使用 PQ 和分层索引（HI）技术的直接的 GPU 加速 ANNS 解决方案。除了所有向量都使用 PQ 压缩外，这个直接解决方案使用与 SPANN 相同的分层索引。收到一个查询后，ANNS 引擎首先遍历导航图以识别 top-m 个最近的 posting lists，并将这些压缩的 posting lists 加载到 GPU 的 HBM 中进行距离计算。然后，GPU 通过计算查询向量与 top-m 最近 posting lists 中每个压缩向量之间的距离来找到 top-n 个候选向量。由于 PQ 对查询准确性有负面影响，这些由 GPU 获得的中间结果需要被重排以提高查询准确性。在重排期间，top-n 候选向量的原始数据应与查询向量进行比较，以找到最终的 top-k 最近邻。</p></li><li><p><strong>观察结果</strong>。令人失望的是，我们发现上述解决方案并未达到预期的性能。为了更好地理解根本原因，我们进行了四个不同的实验来评估 HI、PQ 和 GPU 加速技术的三种组合。在所有实验中，不同的 ANNS 系统必须满足相同水平的查询准确性。如图4a所示，与 SPANN 提出的 HI 相比，PQ 和 GPU 加速都无法降低端到端的查询延迟。尽管“HI+GPU”可以显著降低距离计算的延迟，但在 CPU 和 GPU 之间传输 posting lists 的开销（即 CudaMemcpy）抵消了 GPU 加速带来的好处。对于“HI+PQ”，它仍然使用 CPU 来处理基于 PQ 的 posting lists。由于向量使用 PQ 进行了压缩，从 SSD 加载基于 PQ 的 posting lists 到主内存的 I/O 延迟降低了。然而，CPU 在计算查询向量和压缩向量之间距离时面临新的挑战，即密集的内存访问，导致端到端查询延迟显著增加。对于“HI+PQ+GPU”，距离计算的延迟降低到极低的水平。然而，CudaMemcpy 和额外的重排过程带来了巨大的开销，抵消了使用 GPU 的好处。此外，如图4b所示，这些组合没有一个能实现比单独使用 HI 的原始 SPANN 更高的吞吐量。特别是，直接将 PQ 应用于 SPANN 甚至会使其 QPS 显著降低 65%。</p></li><li><p><img src="'+N+'" alt="image4" loading="lazy"></p></li><li><p><strong>根本原因</strong>。为了揭示这种性能下降的根本原因，我们测量了每个 ANNS 查询平均所需的 I/O 次数和跨 SSD、主内存和 GPU HBM 传输的数据量。如图4c所示，尽管 PQ 技术显著减少了 posting lists 的 I/O 大小，从 12~48 KB 减少到页面粒度（4 KB），但由于重排过程，它使 I/O 次数增加了 70%。结果，I/O 性能瓶颈从 SSD 的带宽转移到其每秒输入/输出操作数（IOPS）。此外，如图4d所示，大量的 posting lists 在 CPU 和 GPU 之间传输，从而抵消了 GPU 加速的好处。</p></li><li><p><img src="'+u+'" alt="image5" loading="lazy"></p></li><li><p><strong>挑战 1</strong>：总的来说，HI、PQ 和 GPU 加速技术的组合导致了比单独采用 HI 的 SPANN 更高的延迟和更低的吞吐量。根本原因是 GPU 的 HBM 仍然无法容纳所有经 PQ 压缩的 posting lists，导致 CPU 和 GPU 之间的大量数据传输成为新的性能瓶颈。如果没有对跨不同设备的数据布局进行精密设计，以及对这三种技术进行仔细的协同，就不可能充分发挥 GPU 在 ANNS 加速方面的潜力。</p></li><li><p><strong>挑战 2</strong>：为了达到相同的查询准确性水平，通常需要一个重排过程来精炼 GPU 生成的中间结果。需要重排的 top-n 向量的数量（即重排数）通常是最终 top-k 最近邻的数倍。为了评估重排数对查询准确性的影响，我们通过线性增加重排数执行了 10,000 次查询。如图5a所示，当重排数设置为 40 时，大约 42% 的查询在 Recall@10 = 1.0 的情况下找到了准确的 top-10 最近邻，而所有查询的平均准确率达到了 Recall@10 = 0.9。在这种情况下，增加重排数仅对落后的查询有益。此外，我们发现对于不同的 ANNS 查询，最小重排数差异很大，如图5b所示。如果所有查询的重排数固定，这种显著的差异通常会导致不必要的 I/O 操作和距离计算。然而，在给定的准确性约束下，为每个查询确定最小重排数是具有挑战性的。</p></li><li><p><strong>挑战 3</strong>：重排过程会引入大量对 SSD 上原始向量的 I/O 请求。原始向量的大小通常在 128 字节到 384 字节之间，而现代 NVMe SSD 的最小操作单元通常是页面（4 KB）。这种粒度上的不匹配通常会导致显著的读放大，从而在重排期间导致极低的 I/O 效率。幸运的是，我们发现这些需要重排的向量通常彼此高度相似。这种相似性为通过精心组织 SSD 上的数据布局来减轻读放大提供了机会。</p></li></ul><h2 id="iii、fusionanns-概述" tabindex="-1"><a class="header-anchor" href="#iii、fusionanns-概述"><span>III、FusionANNS 概述</span></a></h2><ul><li><p>我们提出了一种多层级索引结构，以实现 CPU/GPU 协同的向量过滤和重排。图6展示了 FusionANNS 架构的概览。</p></li><li><p><img src="'+S+'" alt="image6" loading="lazy"></p></li><li><p><strong>离线处理</strong>：与大多数 ANNS 系统一样，FusionANNS 也以离线方式构建多层级索引。首先，FusionANNS 利用聚类算法将数据集划分为多个 posting lists。然后，使用这些 posting lists 的质心构建一个图索引。之后，FusionANNS 提取每个 posting list 的向量 ID 作为元数据，与导航图一起保存在主内存中。最后，中间的 posting lists 被丢弃，原始向量和基于 PQ 的压缩向量分别存储在 SSD 和 GPU HBM 上。</p></li><li><p><strong>在线处理</strong>：对于一个向量查询，FusionANNS 首先利用 GPU 生成查询向量的距离表，用于后续的 PQ 距离计算（①）。同时，CPU 遍历内存中的图以识别 top-m 个最近的 posting lists（②）。然后，CPU 查询元数据以收集这些候选 posting lists 中的向量 ID（③）。之后，CPU 将这些向量 ID 传输到 GPU，并调用 GPU 内核（④）进行进一步处理。</p></li><li><p>当 GPU 收到向量 ID 后，它首先使用一个并行的哈希模块对它们进行去重（⑤）。对于每个向量 ID，GPU 从 HBM 读取相应的压缩向量，并计算其与查询向量之间的 PQ 距离。在这一步中，GPU 为每个维度分配一个线程来访问距离表中的相应值。然后，一个协调线程累加这些值，以计算每个候选向量的 PQ 距离（⑥）。随后，GPU 对所有距离进行排序，并将 top-n 个向量的 ID 返回给 CPU（⑦）。最后，CPU 使用启发式重排机制（⑧）对这些向量进行重排，并返回最终的 top-k 最近邻。在此阶段，会使用一个冗余感知的 I/O 去重机制来识别重复的 I/O。</p></li></ul><h2 id="iv、fusionanns-设计" tabindex="-1"><a class="header-anchor" href="#iv、fusionanns-设计"><span>IV、FusionANNS 设计</span></a></h2><ul><li>在本节中，我们介绍 FusionANNS 的设计。我们将详细阐述多层级索引的构建、启发式重排机制以及冗余感知的 I/O 去重。</li></ul><h3 id="a-多层级索引" tabindex="-1"><a class="header-anchor" href="#a-多层级索引"><span>A. 多层级索引</span></a></h3><ul><li><p>图7展示了位于主机主内存、GPU HBM 和 SSD 上的多层级索引的结构。我们首先使用分层平衡聚类算法 [34] 迭代地将数据集划分为多个 posting lists。每个 posting list 包含多个向量 ID 和相应的向量内容。posting lists 的数量仅为数据集中向量总数的 10%。为了提高每个簇的质量，我们使用一种复制机制来处理边界问题 [15]。具体来说，当一个向量位于多个簇的边界时，我们根据公式2将这个边界向量分配给一个簇。</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mtable width="100%"><mtr><mtd width="50%"></mtd><mtd><mrow><mi>v</mi><mo>∈</mo><msub><mi>C</mi><mi>i</mi></msub><mo>⇔</mo><mtext>Dist</mtext><mo stretchy="false">(</mo><mi>v</mi><mo separator="true">,</mo><msub><mi>C</mi><mi>i</mi></msub><mo stretchy="false">)</mo><mo>≤</mo><mo stretchy="false">(</mo><mn>1</mn><mo>+</mo><mi>ε</mi><mo stretchy="false">)</mo><mo>×</mo><mtext>Dist</mtext><mo stretchy="false">(</mo><mi>v</mi><mo separator="true">,</mo><msub><mi>C</mi><mn>1</mn></msub><mo stretchy="false">)</mo></mrow></mtd><mtd width="50%"></mtd><mtd><mtext>(2)</mtext></mtd></mtr></mtable><annotation encoding="application/x-tex">v \\in C_i \\Leftrightarrow \\text{Dist}(v, C_i) \\le (1 + \\varepsilon) \\times \\text{Dist}(v, C_1) \\tag{2} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5782em;vertical-align:-0.0391em;"></span><span class="mord mathnormal" style="margin-right:0.03588em;">v</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.07153em;">C</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0715em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">⇔</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord text"><span class="mord">Dist</span></span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.03588em;">v</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.07153em;">C</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0715em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≤</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">ε</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord text"><span class="mord">Dist</span></span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.03588em;">v</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.07153em;">C</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0715em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span><span class="tag"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord text"><span class="mord">(</span><span class="mord"><span class="mord">2</span></span><span class="mord">)</span></span></span></span></span></span></p><p>其中 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>v</mi></mrow><annotation encoding="application/x-tex">v</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.03588em;">v</span></span></span></span> 代表要分配的向量，<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>C</mi><mi>i</mi></msub></mrow><annotation encoding="application/x-tex">C_i</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.07153em;">C</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0715em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 表示第 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>i</mi></mrow><annotation encoding="application/x-tex">i</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6595em;"></span><span class="mord mathnormal">i</span></span></span></span> 个簇。特别地，<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>C</mi><mn>1</mn></msub></mrow><annotation encoding="application/x-tex">C_1</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.07153em;">C</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0715em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 代表离向量 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>v</mi></mrow><annotation encoding="application/x-tex">v</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.03588em;">v</span></span></span></span> 最近的簇。参数 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>ε</mi></mrow><annotation encoding="application/x-tex">\\varepsilon</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">ε</span></span></span></span> 决定了一个向量应同时分配给多个簇的最大距离。为了平衡查询准确性和效率，每个向量最多被分配到八个簇 [15]。</p></li><li><p><img src="'+P+'" alt="image7" loading="lazy"></p></li><li><p><strong>内存中索引</strong>。数据集聚类后，我们使用所有 posting lists 的质心，基于 SPTAG [36] 构建一个图索引，并将其存储在主内存中。通过这个导航图，FusionANNS 可以高效地为查询向量识别 top-m 个最近的 posting lists。这个图是通过不断向一个空图添加新向量来构建的。当一个向量作为新顶点添加时，会创建新的边来连接这个新添加的顶点与其 top-k（通常为 64）个最近邻。然后，其邻近顶点应更新它们的最近邻以限制边的最大数量。与将所有 posting lists 存储在 SSD 上的 SPANN 不同，我们仅提取每个 posting list 的向量 ID 作为元数据（不包括向量内容）并将其存储在内存中，如图7所示。当图索引和元数据生成后，中间的 posting lists 就可以被丢弃。由于图和元数据的内存占用相对较小，FusionANNS 可以使用通用服务器以内存成本高效的方式支持十亿级 ANNS。</p></li><li><p><strong>GPU HBM 中的 PQ 向量</strong>。由于 PQ 可以通过有损压缩显著减少高维向量的内存占用，即使是像 NVIDIA V100 这样拥有 32 GB HBM 的入门级 GPU，也可以在其 HBM 中容纳十亿级数据集的所有压缩向量。在 FusionANNS 中，我们将所有压缩向量固定在 HBM 中，避免了 GPU 和 CPU 之间的大量数据交换，这在之前的 GPU 加速 ANNS 系统 [9, 20, 24] 中是常见的问题。由于内存中索引仍然保留了边界向量复制机制的好处，FusionANNS 可以高效地获取所有候选向量的 ID，然后将这些向量 ID（不包括向量内容）发送到 GPU 进行距离计算。通过这种方式，FusionANNS 也消除了由 CPU 和 GPU 之间有限的 PCIe 带宽引起的性能瓶颈。</p></li><li><p><strong>SSD 上的原始向量</strong>。与基于 IVF 的 SPANN 将所有 posting lists 存储在 SSD 上不同，FusionANNS 只需要在 SSD 上存储用于重排的原始向量。由于原始向量的体积比 posting lists 小近 8 倍，FusionANNS 可以显著减少存储消耗。对于每个查询，由于只有重排过程会产生少量 I/O 请求，FusionANNS 也可以缓解并发查询下 SSD 的 I/O 瓶颈。</p></li><li><p><strong>备注</strong>。总的来说，我们的多层级索引方法与之前由基于 SSD 或 GPU 加速的 ANNS 系统 [9, 15, 22, 37] 提出的分层索引技术有显著不同。它可以显著减少 HBM、主内存和 SSD 上的存储占用。它也显著减少了跨 SSD、CPU 和 GPU 传输的数据量。这种存储节省和传输高效的方法有效地支持了 CPU/GPU 协同过滤和重排，以实现快速和准确的 ANNS。</p></li></ul><h3 id="b-启发式重排" tabindex="-1"><a class="header-anchor" href="#b-启发式重排"><span>B. 启发式重排</span></a></h3><ul><li><p>由于 PQ 在距离计算过程中会导致准确性损失，通常需要一个重排过程来精炼 GPU 报告的中间结果。如第2.3节所述，为了达到相同的查询准确性水平，不同 ANNS 查询的最小重排数量通常差异很大。因此，静态配置重排数量可能会导致不必要的 I/O 操作和距离计算，或导致准确性损失。</p></li><li><p>为了规避这个问题，我们提出了一种启发式重排机制，以最小化 I/O 操作和距离计算。关键思想是保守地设置一个相对较大的重排数以保证高准确性，并在后续搜索对提高查询准确性不再有益时立即终止重排过程。为实现这一目标，我们将重排过程划分为多个小批次（mini-batches）并顺序执行它们。每个小批次包含相同数量的候选向量。由于所有候选向量都按其距离升序排序，较早执行的小批次通常有更高可能性识别出更多属于最终 top-k 最近邻的向量。一个小批次完成后，我们利用一个轻量级的反馈控制模型来检查后续小批次是否有助于提高查询准确性。</p></li><li><p>为了简化问题，我们使用一个优先队列 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>Q</mi></mrow><annotation encoding="application/x-tex">Q</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8778em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">Q</span></span></span></span>（即最大堆）来维护当前的 top-k 最近邻。最初，最大堆是空的。对于每个小批次，我们计算查询向量与该小批次内向量之间的距离，并将距离小于最大堆中当前最大距离的向量插入。当一个小批次完成后，我们根据公式3计算最大堆的变化率：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mtable width="100%"><mtr><mtd width="50%"></mtd><mtd><mrow><mi mathvariant="normal">Δ</mi><mo>=</mo><mfrac><mrow><mi mathvariant="normal">∣</mi><msub><mi>S</mi><mi>n</mi></msub><mo>−</mo><msub><mi>S</mi><mi>n</mi></msub><mo>∩</mo><msub><mi>S</mi><mrow><mi>n</mi><mo>−</mo><mn>1</mn></mrow></msub><mi mathvariant="normal">∣</mi></mrow><mi>k</mi></mfrac></mrow></mtd><mtd width="50%"></mtd><mtd><mtext>(3)</mtext></mtd></mtr></mtable><annotation encoding="application/x-tex">\\Delta = \\frac{|S_n - S_n \\cap S_{n-1}|}{k} \\tag{3} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">Δ</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.113em;vertical-align:-0.686em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.427em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.03148em;">k</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord">∣</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.05764em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">n</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.05764em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">n</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">∩</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.05764em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">n</span><span class="mbin mtight">−</span><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span><span class="mord">∣</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.686em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span></span><span class="tag"><span class="strut" style="height:2.113em;vertical-align:-0.686em;"></span><span class="mord text"><span class="mord">(</span><span class="mord"><span class="mord">3</span></span><span class="mord">)</span></span></span></span></span></span></p><p>其中 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>S</mi><mi>n</mi></msub></mrow><annotation encoding="application/x-tex">S_n</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.05764em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">n</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 和 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>S</mi><mrow><mi>n</mi><mo>−</mo><mn>1</mn></mrow></msub></mrow><annotation encoding="application/x-tex">S_{n-1}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8917em;vertical-align:-0.2083em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.05764em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">n</span><span class="mbin mtight">−</span><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span></span></span></span> 分别代表在第 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>n</mi></mrow><annotation encoding="application/x-tex">n</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">n</span></span></span></span> 个和第 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>n</mi><mo>−</mo><mn>1</mn></mrow><annotation encoding="application/x-tex">n-1</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6667em;vertical-align:-0.0833em;"></span><span class="mord mathnormal">n</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">1</span></span></span></span> 个小批次刚完成时最大堆中向量 ID 的集合。<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>k</mi></mrow><annotation encoding="application/x-tex">k</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.03148em;">k</span></span></span></span> 代表最大堆中维护的向量数量，即最终最近邻的数量。如果连续 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>β</mi></mrow><annotation encoding="application/x-tex">\\beta</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.05278em;">β</span></span></span></span> 次小批次的最大堆变化率小于给定阈值 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>ε</mi></mrow><annotation encoding="application/x-tex">\\varepsilon</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">ε</span></span></span></span>，我们则终止重排过程。</p></li><li><p><img src="'+x+'" alt="algo1" loading="lazy"></p></li><li><p>算法1展示了启发式重排的伪代码。我们首先将最大堆 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>Q</mi></mrow><annotation encoding="application/x-tex">Q</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8778em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">Q</span></span></span></span> 初始化为 NULL，并使用一个 <code>StabilityCounter</code> 来记录变化率持续低于 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>ε</mi></mrow><annotation encoding="application/x-tex">\\varepsilon</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">ε</span></span></span></span> 的次数。<code>Tasks</code> 的大小表示需要分批重排的向量总数。参数 <code>BatchSize</code> 表示一个小批次中的候选向量数量。对于每个小批次，我们在处理该小批次中的任务之前，从 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>Q</mi></mrow><annotation encoding="application/x-tex">Q</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8778em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">Q</span></span></span></span> 中检索 top-k 向量的 ID（第4行）。然后，我们顺序执行每个任务，包括从 SSD 读取原始向量，计算其与查询向量的距离，如果其距离小于最大堆中的最大值，则将其插入 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>Q</mi></mrow><annotation encoding="application/x-tex">Q</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8778em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">Q</span></span></span></span> 中。当一个小批次完成后，我们从 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>Q</mi></mrow><annotation encoding="application/x-tex">Q</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8778em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">Q</span></span></span></span> 中收集更新后的 top-k 向量的 ID，并计算这两个连续小批次之间 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>Q</mi></mrow><annotation encoding="application/x-tex">Q</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8778em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">Q</span></span></span></span> 的变化率 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi mathvariant="normal">Δ</mi></mrow><annotation encoding="application/x-tex">\\Delta</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">Δ</span></span></span></span>（第9-10行）。如果变化率低于给定阈值 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>ε</mi></mrow><annotation encoding="application/x-tex">\\varepsilon</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">ε</span></span></span></span>，我们将 <code>StabilityCounter</code> 加一。一旦 <code>StabilityCounter</code> 大于给定阈值 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>β</mi></mrow><annotation encoding="application/x-tex">\\beta</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.05278em;">β</span></span></span></span>，重排过程即被终止。相反，如果变化率超过阈值 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>ε</mi></mrow><annotation encoding="application/x-tex">\\varepsilon</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">ε</span></span></span></span>，我们重置 <code>StabilityCounter</code> 并继续执行后续的小批次。最后，我们返回 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>Q</mi></mrow><annotation encoding="application/x-tex">Q</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8778em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">Q</span></span></span></span> 中的最终 top-k 向量。</p></li><li><p><strong>备注</strong>。我们的启发式重排算法可以在保证高准确性的同时，最小化对 SSD 的 I/O 请求和 CPU 资源消耗，并最终降低重排的延迟。</p></li></ul><h3 id="c-冗余感知的-i-o-去重" tabindex="-1"><a class="header-anchor" href="#c-冗余感知的-i-o-去重"><span>C. 冗余感知的 I/O 去重</span></a></h3><ul><li><p>FusionANNS 使用 SSD 上的原始向量来重排 GPU 返回的中间结果。一个直接的方法是按顺序在 SSD 页面上存储所有原始向量。然而，由于一个原始向量（128-384字节）远小于页面粒度（4KB），对这些原始向量的单独请求通常会导致显著的读放大。此外，由于重排过程引入了大量随机和小型的 I/O 操作，I/O 延迟对端到端查询延迟有关键影响。与大多数基于 SSD 的 ANNS 系统 [15] 一样，我们采用直接 I/O [38, 39] 来充分利用现代 NVMe SSD 的低延迟特性。为了进一步提高 I/O 效率，我们首先优化数据布局以提高 SSD 上的空间局部性。然后，我们利用冗余感知的 I/O 去重来减轻读放大的影响。</p></li><li><p><strong>优化的存储布局</strong>。尽管需要重排的向量是通过 PQ 距离获得的，但它们都与查询向量高度相似，这使得它们通常在空间上彼此接近。这种相似性为通过精心组织 SSD 上的数据布局来减轻读放大提供了机会。具体来说，当离线创建内存中索引时，对于导航图中的每个质心，我们使用一个桶来存储一组最接近该质心的原始向量。我们注意到桶之间没有重复的向量。对于每个桶，如果它没有与 SSD 页面对齐，我们使用最大-最小算法 [40] 基于未对齐部分的大小来合并桶，以最小化 SSD 页面上的空闲空间。最后，我们将所有桶分组为一个单独的文件并将其存储在 SSD 上，并使用一个表在内存中维护向量和 SSD 页面之间的映射关系。</p></li><li><p><strong>批次内和批次间的 I/O 去重</strong>。得益于优化的数据布局，我们设计了两种 I/O 去重机制，包括在一个小批次内合并映射到同一 SSD 页面的 I/O，以及利用 DRAM 缓冲区消除后续小批次中的冗余 I/O。这里，我们用一个简单的例子来描述这些机制，如图8所示。假设重排过程有两个小批次，其中小批次0的任务是重排向量：V2、V4 和 V6。小批次1的任务是重排向量：V5、V8 和 V9。当小批次0执行时，它首先查询映射表以获取所请求向量对应的 SSD 页面 ID。由于 V2 和 V6 都存储在同一个 SSD 页面 P0 上，我们可以合并这两个 I/O 请求，只读取一个 SSD 页面来获取 V2 和 V6。由于 P0 和 P2 不存在于 DRAM 缓冲区中，我们通过两个 I/O 请求直接将它们读入 DRAM 缓冲区。在小批次1中，尽管 V5、V8 和 V9 存储在不同的 SSD 页面中，但 DRAM 缓冲区已经包含了包含 V5 的 P2。因此，小批次1只需要通过两个 I/O 请求读取 P1 和 P3。</p></li><li><p><img src="'+v+'" alt="image8" loading="lazy"></p></li><li><p><strong>备注</strong>。我们优化了 SSD 上的数据布局，以实现批次内和批次间的 I/O 去重机制，这最终减轻了读放大的影响并提高了 I/O 效率。</p></li></ul><h2 id="v、实现" tabindex="-1"><a class="header-anchor" href="#v、实现"><span>V、实现</span></a></h2><ul><li><p>我们使用 22K 行 C++ 和 CUDA 代码实现了 FusionANNS 的系统原型。FusionANNS 可以广泛部署在配备入门级 GPU 的通用服务器上。与大多数 ANNS 系统 [14, 15, 22, 41] 一样，我们使用每个 CPU 线程处理一个单独的查询。</p></li><li><p><strong>无竞争的 GPU 内存管理</strong>。FusionANNS 为并发的 ANNS 查询专门实现了一个 GPU 内存管理器。在系统初始化期间，我们首先将压缩向量加载到 GPU 的 HBM 中，并将剩余空间用作内存池。然后，我们将内存池划分为多个独立的块，每个块分配给一个查询作为工作内存。一旦一个查询完成，其块可以分配给其他待处理的查询。这种方法可以避免频繁的内存分配和查询之间的锁竞争，从而提高系统性能。</p></li><li><p><strong>高效的 GPU 内核</strong>。对于每个向量，我们根据其维度分配多个 GPU 线程来并行计算距离。此外，我们设计了一个内核来支持使用哈希算法并行去重向量 ID。对于一个候选向量 ID 列表，我们为每个向量 ID 分配一个 GPU 线程，并使用自旋锁来确保一次只有一个线程可以访问和更新哈希表条目。这种方法可以充分利用 GPU 的高并行性来加速去重。</p></li></ul><h2 id="vi、评估" tabindex="-1"><a class="header-anchor" href="#vi、评估"><span>VI、评估</span></a></h2><ul><li><p>我们的实验在两台服务器上进行，都使用 Ubuntu 22.04.4 LTS 操作系统。一台配备了两颗 2.2 GHz 64 核的 Intel Xeon CPU、64 GB 主内存、一块带 32 GB HBM 的入门级 NVIDIA V100 GPU，以及一块 2 TB 存储容量的三星 990Pro SSD。这台服务器用于评估 FusionANNS 和其他基于 SSD 的 ANNS 解决方案。另一台服务器配备了相同的 CPU 和 GPU，但拥有 1 TB 主机内存。这台大内存服务器用于评估一个 GPU 加速的内存 ANNS 解决方案。</p></li><li><p><strong>基准测试</strong>。在我们的实验中，我们使用了三个由先前研究 [14, 15, 22] 广泛使用的标准十亿级数据集 [42]，如表1所示。每个基准测试都使用一组查询向量来模拟工作负载。</p></li><li><p><img src="'+w+'" alt="table1" loading="lazy"></p></li><li><p><strong>对比方案</strong>。我们将 FusionANNS 与三个为十亿级数据集设计的代表性 ANNS 解决方案进行比较，包括两个基于 SSD 的解决方案和一个 GPU 加速的内存解决方案。我们没有评估使用 IVFPQ [32] 的基于加速器的解决方案，因为其低准确性无法满足现实世界应用的需求，正如许多先前研究 [15, 22, 41, 43] 所报道的那样。</p><ul><li><strong>SPANN</strong> [15] 是使用 IVF 索引的最先进的基于 SSD 的 ANNS 解决方案。它专为低延迟而设计。</li><li><strong>DiskANN</strong> [22] 是一个使用图索引的基于 SSD 的 ANNS 解决方案。它实现了高吞吐量，但延迟极高。</li><li><strong>RUMMY</strong> [9] 是使用 IVF 索引的最先进的 GPU 加速的内存 ANNS 解决方案。它将所有向量及其索引完全存储在主机内存中。我们扩展了 RUMMY 以支持高准确性查询，通过采用先进的 IVF 索引 [15]，而不会导致任何性能下降。</li></ul></li><li><p><strong>性能指标</strong>。我们使用每秒查询数（QPS）和平均延迟来评估各种 ANNS 系统的性能。与先前的研究 [14, 19, 44] 一样，除非另有说明，查询准确性通过 Recall@10 进行评估，它代表 top-10 结果中包含真实最近邻的比例。为了达到给定的准确性水平，例如 Recall@10=0.9，我们可以在 FusionANNS 中为不同的数据集调整两个参数，即从图索引中检索的 top-m 最近 posting lists 的数量，以及需要重排过程的 top-n 候选向量的数量。</p></li></ul><h3 id="a-性能" tabindex="-1"><a class="header-anchor" href="#a-性能"><span>A. 性能</span></a></h3><ul><li><p>我们在相同的查询准确性约束下测量了不同 ANNS 系统的 QPS 和延迟。对于这些实验，我们逐渐增加并发查询的线程数，直到这些系统达到峰值 QPS。</p></li><li><p><strong>在不同数据集下的性能</strong>。我们使用三个数据集将 FusionANNS 与其他 ANNS 系统进行比较。图9a和图9b分别显示了在 Recall@10=90% 准确性水平下的 QPS 和延迟。与基于 SSD 的 SPANN 和 DiskANN 相比，FusionANNS 的 QPS 分别显著提高了 9.4-13.1 倍和 3.2-4.3 倍。尽管 SPANN 显示出非常低的延迟，但其吞吐量与其他 ANNS 系统相比相当低。相比之下，FusionANNS 实现了与 SPANN 相当的低延迟，但显著提高了吞吐量。这些结果表明，FusionANNS 为这些十亿级数据集同时实现了高吞吐和低延迟。这种改进主要源于多层级索引所支持的 CPU/GPU 协同过滤和重排技术。因为 FusionANNS 可以避免 CPU 和 GPU 之间的大量数据交换，并且可以减轻 SSD 上的不必要 I/O 操作，它消除了由于有限 PCIe 带宽造成的 I/O 性能瓶颈。与 GPU 加速的内存解决方案 RUMMY 相比，FusionANNS 在保持低延迟的同时，QPS 提高了 2-4.9 倍。值得注意的是，RUMMY 对于 DEEP1B 数据集的性能远低于其他数据集。原因在于，较大数据集从主内存到 GPU HBM 的数据传输消耗了更多的 PCIe 带宽，使得 CPU 和 GPU 之间的带宽瓶颈更加突出。相反，FusionANNS 只需要在 CPU 和 GPU 之间传输轻量的向量 ID，而不是向量内容。因此，FusionANNS 相对于 RUMMY 实现了显著的性能提升。</p></li><li><p><img src="'+y+'" alt="image9" loading="lazy"></p></li><li><p><strong>在不同准确性水平下的性能</strong>。为了评估 FusionANNS 在不同准确性水平下的性能，我们将 Recall@10 从 90% 更改为 98%。图10a和图10b分别显示了使用 SIFT1B 数据集在不同准确性水平下的 QPS 和延迟。所有结果都对 SPANN 进行了归一化。FusionANNS 相较于 SPANN 和 DiskANN 实现了约 9.4-11.7 倍和 3.2 倍的 QPS 提升。随着查询准确性的增加，FusionANNS 相较于 SPANN 实现了更高的 QPS 提升，并且在更高准确性的约束下，其延迟甚至远低于内存中的 RUMMY。根本原因在于 CPU/GPU 协同过滤机制可以有效地消除主内存和 GPU HBM 之间的数据交换，因此可以扩展搜索空间以满足更高的准确性水平，同时仍保持高性能。相比之下，其他 ANNS 解决方案在搜索空间变大时会引起更多的 I/O 操作和距离计算。</p></li><li><p><img src="'+A+'" alt="image10" loading="lazy"></p></li></ul><h3 id="b-可扩展性" tabindex="-1"><a class="header-anchor" href="#b-可扩展性"><span>B. 可扩展性</span></a></h3><ul><li><p>ANNS 系统的吞吐量与 CPU 线程数高度相关。为了评估不同 ANNS 系统的性能可扩展性，我们以 2 的指数因子增加线程数。</p></li><li><p>图11显示了不同 ANNS 系统在使用不同线程数时的 QPS 和延迟。当线程数从 1 增加到 64 时，FusionANNS 的 QPS 呈现显著增长。对于所有 ANNS 系统，当仅使用一个线程时，QPS 几乎相同。然而，当线程数增加到 64 时，FusionANNS 的 QPS 相较于 SPANN、DiskANN 和 RUMMY 分别显著提高了 13.2 倍、3.8 倍和 5.1 倍，同时保持了低延迟。SPANN 仅用 4 个线程就达到了其峰值 QPS，并且其延迟随着更多线程显著增加。值得注意的是，对于 SIFT1B 和 SPACEV1B 数据集，RUMMY 的 QPS 在 16 个线程时达到峰值，然后明显下降。同时，当线程数大于 16 时，RUMMY 的延迟也显著增加。这种有限可扩展性的原因在于，更多的并发查询引起了 CPU 和 GPU 之间大量的数据传输，导致了显著的 PCIe 带宽争用。由于 DEEP1B 数据集的向量尺寸更大，RUMMY 遭受了更严重的带宽争用，因此其 QPS 甚至低于 DiskANN，如图11f所示。FusionANNS 即使使用有限的内存资源也显示出比其他系统更好的可扩展性，因为它消除了 CPU 和 GPU 之间的数据交换，并且也显著提高了 SSD 上的 I/O 效率。</p></li><li><p><img src="'+M+'" alt="image11" loading="lazy"></p></li></ul><h3 id="c-单项技术的有效性" tabindex="-1"><a class="header-anchor" href="#c-单项技术的有效性"><span>C. 单项技术的有效性</span></a></h3><ul><li><p>在本小节中，我们使用 SIFT1B 评估 FusionANNS 中各项技术的有效性。我们首先使用我们的多层级索引技术进行一个基于 CPU 的变体实验（即 MI(CPU)），其中我们用主机 CPU 替代 GPU 来处理压缩向量。然后，我们逐步添加 FusionANNS 的其他技术，以评估它们对性能和 I/O 次数的影响。</p></li><li><p>如图12a所示，与 SPANN 相比，带 CPU 的多层级索引，即 MI(CPU)，实现了 1.5-4.2 倍的更高 QPS，但延迟非常高。然而，带 GPU 的多层级索引，即 MI(GPU)，可以显著降低与 MI(CPU) 相比的延迟。它还将 QPS 相较于 SPANN 提高了 5.9-6.8 倍。这是因为 CPU 遭受高延迟的 DRAM 访问，而 GPU HBM 的高带宽和并行内存访问能力使 MI(GPU) 能高效地处理 PQ 距离计算。此外，多层级索引使 CPU 只需向 GPU 传输轻量的向量 ID，缓解了由于 PCIe 带宽争用造成的性能瓶颈。在多层级索引的基础上，启发式重排（HR）和冗余感知的 I/O 去重可以进一步将延迟降低高达 39%，并将 QPS 提高高达 17%。</p></li><li><p>图12c显示了每个查询引发的平均 I/O 次数。显然，当需要保证更高准确性水平时，SPANN 发起的 I/O 请求数量显著增加。多层级索引技术可以比 SPANN 减少 3.2-3.8 倍的 I/O 次数。启发式重排和冗余感知的 I/O 去重可以进一步将 I/O 次数分别减少高达 30% 和 23%。此外，SPANN 发起的每个 I/O 操作通常涉及多个 SSD 页面，而其他 ANNS 系统只涉及一个页面。FusionANNS 不仅显著减少了每个查询的 I/O 次数，还减小了 I/O 的大小，从而实现了实质性的性能提升。</p></li><li><p><img src="'+U+'" alt="image12" loading="lazy"></p></li></ul><h3 id="d-成本和内存效率" tabindex="-1"><a class="header-anchor" href="#d-成本和内存效率"><span>D. 成本和内存效率</span></a></h3><ul><li><p>我们在成本和内存效率方面将 FusionANNS 与其他 ANNS 系统进行比较。我们使用 QPS/$ 和 QPS/GB 来分别评估成本和内存效率。系统成本包括服务器成本（约 5000 美元，包括 CPU 和服务器机箱）、内存成本（约 10 美元/GB）、存储成本（一块 2TB 三星 SSD 约 400 美元）和 GPU 成本（一块 Nvidia V100 约 3000 美元）。这些价格参考自亚马逊。为了公平比较，我们只评估 FusionANNS、SPANN 和 RUMMY，因为它们实现了相似的低延迟，但排除了 DiskANN，因为它以高延迟为代价来提高 QPS。</p></li><li><p>如表2所示，与 SPANN 和 RUMMY 相比，FusionANNS 在 QPS/$ 上分别实现了 5.67-8.78 倍和 2.25-6.82 倍的提升。这主要是由于 FusionANNS 的显著性能。此外，FusionANNS 实现了更高的内存效率，如表3所示。具体来说，对于大容量数据集 DEEP1B，FusionANNS 的内存效率分别比 SPANN 和 RUMMY 提高了 13.1 倍和 32.4 倍。FusionANNS 显著提高了成本和内存效率，因为我们的多层级索引技术可以显著提高性能并减少内存占用。</p></li><li><p><img src="'+b+'" alt="table2" loading="lazy"></p></li><li><p><img src="'+k+'" alt="table3" loading="lazy"></p></li></ul><h2 id="vii、相关工作" tabindex="-1"><a class="header-anchor" href="#vii、相关工作"><span>VII、相关工作</span></a></h2><ul><li><p><strong>内存 ANNS 解决方案</strong>。ANNS 已经被广泛研究了数十年，主要关注内存中的索引技术 [16, 17, 31, 33, 36]。层次化可导航小世界图（HNSW）[17] 在内存中维护一个多层可导航小世界图以实现快速 ANNS。空间分区树和图（SPTAG）[36] 利用相对邻域图和空间分区树来找到几个种子点以加速图遍历。然而，现有的内存 ANNS 算法需要大量的内存资源来维护原始向量及其索引。巨大的内存需求显著增加了总拥有成本，阻碍了 ANNS 向大规模数据集的扩展。FusionANNS 利用大容量 SSD 来支持大规模数据集，并通过支持多层级索引的系统优化实现了高性能和高成本效益。</p></li><li><p><strong>基于 SSD 的 ANNS 解决方案</strong>。许多近期研究提出了分层索引来减少十亿级数据集的内存占用，例如 DiskANN [22]、SPANN [15]、Starling [41]、BBANN [45] 和 GRIP [46]。这些方案利用了现代 SSD 的特性来优化向量索引技术。SmartANNS [19] 探索了用于基于 SmartSSD 的 ANNS 的分层索引技术。它利用多个 SmartSSD 的内部 PCIe 带宽来缓解 I/O 瓶颈，实现了对十亿级 ANNS 的近线性可扩展性。然而，由于并发查询之间的严重 I/O 争用，基于 SSD 的 ANNS 系统的吞吐量相当有限，使得它们难以满足高吞吐量的要求。FusionANNS 通过新颖的多层级索引结构和 CPU/GPU 协同搜索显著减少了每个查询的 I/O，从而实现了高吞吐和低延迟。</p></li><li><p><strong>基于加速器的 ANNS 解决方案</strong>。一些近期的研究 [24-26, 47] 利用 GPU 来加速基于图的 ANNS 中涉及的图遍历。此外，许多工作利用了 PQ 技术 [32, 48]、GPU [20, 21] 和 FPGA [49-51] 来加速基于 IVF 的 ANNS。然而，由于 GPU 和 FPGA 的内存容量有限 [24-26, 47, 49]，这些方法大多数只能支持小规模数据集，或者不能保证高准确性 [49-51]。尽管最先进的 RUMMY [9] 用主机内存扩展了 GPU 内存，并提出了一种重排序流水线技术来支持十亿级数据集，但其性能仍然受限于 CPU 和 GPU 之间的密集数据传输。通过分层索引、PQ 和 GPU 加速技术的仔细协作，FusionANNS 可以消除 GPU 和 CPU 之间的数据交换，从而为大规模数据集实现高吞吐和低延迟的 ANNS，同时仍然保证高准确性。</p></li></ul><h2 id="viii、结论" tabindex="-1"><a class="header-anchor" href="#viii、结论"><span>VIII、结论</span></a></h2><ul><li>我们提出了 FusionANNS，一个用于十亿级 ANNS 的“CPU + GPU”协同处理架构。FusionANNS 利用 GPU/CPU 协同过滤和重排机制来显著提高 ANNS 的性能和成本效益，同时仍然保证高准确性。与最先进的基于 SSD 的 ANNS 解决方案 SPANN 相比，FusionANNS 在保持低延迟的同时，显著提高了并发查询的吞吐量。此外，FusionANNS 也比 GPU 加速的内存 ANNS 解决方案 RUMMY 实现了更高的吞吐量和成本效益。</li></ul>',38))])}const F=m(I,[["render",G]]),z=JSON.parse('{"path":"/article/reading/A-%E5%90%91%E9%87%8F%E6%95%B0%E6%8D%AE%E5%BA%93/U-FusionANNS/FusionANNS.html","title":"FusionANNS：一种用于十亿级近似最近邻搜索的高效 CPU/GPU 协同处理架构","lang":"zh-CN","frontmatter":{"date":"2024-09-26T00:00:00.000Z","category":["AI","Database"],"tag":["ANNS","Vector Search","GPU"],"feed":false,"seo":false,"head":[]},"headers":[{"level":2,"title":"摘要","slug":"摘要","link":"#摘要","children":[]},{"level":2,"title":"I、引言","slug":"i、引言","link":"#i、引言","children":[]},{"level":2,"title":"II、背景与动机","slug":"ii、背景与动机","link":"#ii、背景与动机","children":[{"level":3,"title":"A. ANNS 的索引技术","slug":"a-anns-的索引技术","link":"#a-anns-的索引技术","children":[]},{"level":3,"title":"B. 乘积量化","slug":"b-乘积量化","link":"#b-乘积量化","children":[]},{"level":3,"title":"C. 主要思想与挑战","slug":"c-主要思想与挑战","link":"#c-主要思想与挑战","children":[]}]},{"level":2,"title":"III、FusionANNS 概述","slug":"iii、fusionanns-概述","link":"#iii、fusionanns-概述","children":[]},{"level":2,"title":"IV、FusionANNS 设计","slug":"iv、fusionanns-设计","link":"#iv、fusionanns-设计","children":[{"level":3,"title":"A. 多层级索引","slug":"a-多层级索引","link":"#a-多层级索引","children":[]},{"level":3,"title":"B. 启发式重排","slug":"b-启发式重排","link":"#b-启发式重排","children":[]},{"level":3,"title":"C. 冗余感知的 I/O 去重","slug":"c-冗余感知的-i-o-去重","link":"#c-冗余感知的-i-o-去重","children":[]}]},{"level":2,"title":"V、实现","slug":"v、实现","link":"#v、实现","children":[]},{"level":2,"title":"VI、评估","slug":"vi、评估","link":"#vi、评估","children":[{"level":3,"title":"A. 性能","slug":"a-性能","link":"#a-性能","children":[]},{"level":3,"title":"B. 可扩展性","slug":"b-可扩展性","link":"#b-可扩展性","children":[]},{"level":3,"title":"C. 单项技术的有效性","slug":"c-单项技术的有效性","link":"#c-单项技术的有效性","children":[]},{"level":3,"title":"D. 成本和内存效率","slug":"d-成本和内存效率","link":"#d-成本和内存效率","children":[]}]},{"level":2,"title":"VII、相关工作","slug":"vii、相关工作","link":"#vii、相关工作","children":[]},{"level":2,"title":"VIII、结论","slug":"viii、结论","link":"#viii、结论","children":[]}],"git":{"createdTime":1787540590000,"updatedTime":1787540590000,"contributors":[{"name":"z-ben","username":"z-ben","email":"12800262+z-ben@user.noreply.gitee.com","commits":1,"url":"https://github.com/z-ben"}]},"readingTime":{"minutes":43.88,"words":13164},"filePathRelative":"article/reading/A-向量数据库/U-FusionANNS/FusionANNS.md","localizedDate":"2024年9月26日"}');export{F as comp,z as data};
